/* @socom-skeleton body EntityIsValid__7CEntityFP7CEntity */
bool CEntity::EntityIsValid(CEntity* entity)
{
	bool valid = false;
	auto it = m_list.begin();
	while (it != m_list.end())
	{
		if (*it == entity)
		{
			valid = true;
			break;
		}
		
		++it;
	}

	return valid;
}

